import{_ as l,C as n,o as d,c as u,a2 as c,b as r,w as e,a,E as i,a3 as s}from"./chunks/framework.BaXgE4DV.js";const m=JSON.parse('{"title":"알림","description":"","frontmatter":{},"headers":[],"relativePath":"features/notifications.md","filePath":"features/notifications.md","lastUpdated":1792234772000}'),h={name:"features/notifications.md"};function p(C,t,A,E,f,q){const o=n("Mermaid");return d(),u("div",null,[t[2]||(t[2]=c(`<h1 id="알림" tabindex="-1">알림 <a class="header-anchor" href="#알림" aria-label="Permalink to &quot;알림&quot;">​</a></h1><p>푸시는 Firebase Cloud Messaging(FCM)으로 보냅니다. 서버는 Cloud Functions 트리거와 스케줄러, 웹 클라이언트는 서비스 워커(<code>public/firebase-messaging-sw.js</code>)와 <code>src/lib/pushNotifications.js</code>가 담당합니다. iOS·Android 앱은 네이티브 푸시(<code>src/lib/native/push.js</code>)를 쓰고, 매일 알림은 서버 푸시 대신 휴대폰이 직접 띄웁니다. → <a href="#app">앱 (iOS·Android)</a></p><h2 id="알림-종류" tabindex="-1">알림 종류 <a class="header-anchor" href="#알림-종류" aria-label="Permalink to &quot;알림 종류&quot;">​</a></h2><table tabindex="0"><thead><tr><th>종류 (<code>data.type</code>)</th><th>언제</th><th>받는 사람</th><th>끄는 설정</th><th>클릭 시</th><th>중복 방지 키</th></tr></thead><tbody><tr><td><code>circle_post</code></td><td>Circle에 새 글 (<code>onGratitudeCreated</code>). 그 Circle의 첫 나눔이면 <code>variant: &quot;first&quot;</code> → <a href="#first-share">첫 나눔</a></td><td>작성자를 뺀 Circle 멤버 (작성자를 차단한 멤버 제외). 자동 숨김된 글은 보내지 않음</td><td><code>circlePostNotice</code></td><td><code>/gratitude/{id}</code></td><td><code>circle_post_{gratitudeId}</code></td></tr><tr><td><code>circle_post</code> (<code>variant: &quot;first_followup&quot;</code>)</td><td>첫 나눔 뒤 24시간 동안 다른 사람의 공감·댓글이 없음 (<code>firstShareFollowup</code>, Cloud Tasks). 밤(KST 22:00–08:59)이면 다음 09:00 → <a href="#first-share-followup">리더 알림</a></td><td>그 Circle의 리더 한 명. 리더당 하루(KST) 1회</td><td><code>circlePostNotice</code></td><td><code>/gratitude/{id}</code></td><td><code>first_followup_{gratitudeId}</code> (+ 하루 상한 <code>first_followup_leader_{uid}_{YYYYMMDD}</code>)</td></tr><tr><td><code>reaction</code></td><td>내 글에 새 리액션 (<code>onReactionUpdated</code>)</td><td>글 작성자 (본인 리액션, 작성자가 차단한 사람의 리액션 제외)</td><td><code>reactionNotice</code></td><td><code>/gratitude/{id}</code></td><td><code>reaction_{gratitudeId}_{reactorUid}_{emoji}</code></td></tr><tr><td><code>daily_reminder</code></td><td>설정한 시각 (<code>sendDailyReminder</code>). 앱은 휴대폰 자체 알림</td><td>오늘 아직 쓰지 않은 사용자 (앱이 로컬 알림을 맡은 사용자 제외)</td><td><code>dailyReminder</code></td><td><code>/write</code></td><td><code>daily_reminder_{uid}_{YYYYMMDD}_{HHMM}</code></td></tr><tr><td><code>question_selected</code></td><td>제안한 질문이 처음 선정됨 (<code>reviewQuestion</code>)</td><td>제안자</td><td>없음</td><td><code>/mypage#questions</code></td><td><code>question_selected_{questionId}</code> (+ 처음 선정일 때만 보냄)</td></tr><tr><td><code>report</code></td><td>새 신고 접수 (<code>onReportCreated</code>)</td><td>운영자(<code>isAdmin</code>) 전원</td><td>없음</td><td><code>/admin?tab=reports</code></td><td><code>report_{reportId}</code> (+ 대상의 첫 열린 신고일 때만, 차단 신고는 보내지 않음)</td></tr></tbody></table><p>알림 문구 예:</p><ul><li>Circle 새 글: &quot;{공개 이름}님이 감사를 기록했어요&quot; / 본문은 글 제목. 이름을 모르면 &quot;누군가 감사를 기록했어요&quot;. <a href="/grato-docs/features/circles#open-circle">모두의 감사방</a> 글은 보내지 않음</li><li>Circle 첫 나눔: &quot;{공개 이름}님이 Circle에 처음 감사를 나눴어요 🌱&quot; / 본문은 글 제목. 이름을 모르면 &quot;새 멤버가 Circle에 처음 감사를 나눴어요 🌱&quot; → <a href="#first-share">첫 나눔</a></li><li>첫 나눔 리더 알림: &quot;{공개 이름}님이 처음 나눈 감사가 있어요&quot; / &quot;{글 제목} · 공감이나 댓글로 반겨 줄 수 있어요&quot;. 이름을 모르면 &quot;새 멤버가 처음 나눈 감사가 있어요&quot; → <a href="#first-share-followup">리더 알림</a></li><li>리액션: &quot;{공개 이름}님이 공감했어요 ❤️&quot; / 본문은 글 제목. 모두의 감사방 글이면 공개 이름 대신 공감한 사람의 그 방 별명. 이름(별명)이 없으면 &quot;누군가 공감했어요 ❤️&quot;(&quot;누군가님이&quot;라고 쓰지 않음, <code>utils/noticeCopy.ts</code>)</li><li>매일 알림: &quot;오늘의 감사를 기록해보세요 🙏&quot; / &quot;하루를 돌아보며 감사한 순간을 적어볼까요?&quot; — 쓰기로 한 때를 골랐으면 그 때를 말함 → <a href="#daily-reminder-copy">매일 알림 문구</a></li><li>질문 선정: &quot;제안한 질문이 선정됐어요 🎉&quot; / 본문은 질문 문구 → <a href="#question-selected">질문 선정 알림</a></li><li>신고(운영자): &quot;새 신고가 접수됐어요&quot; / &quot;감사 글 · 욕설·괴롭힘. 24시간 안에 확인해주세요&quot;. 잠금 화면에 보이므로 신고된 내용과 이름은 넣지 않음 → <a href="/grato-docs/features/safety#report-trigger">신고</a></li></ul><p>차단은 그 사람 <strong>때문에</strong> 오는 알림(새 글, 리액션)을 막습니다. 차단 여부는 보내기 전에 받는 사람의 차단 목록(<code>users/{uid}/blocks</code>)을 읽어 확인합니다. → <a href="/grato-docs/features/safety#block">차단</a></p><h2 id="first-share" tabindex="-1">첫 나눔 알림 <a class="header-anchor" href="#first-share" aria-label="Permalink to &quot;첫 나눔 알림 {#first-share}&quot;">​</a></h2><p>한 사람이 <strong>그 Circle에</strong> 처음 나눈 글은 멤버가 받는 새 글 알림의 문구만 바뀝니다. 받는 사람·설정·횟수는 보통 새 글 알림과 같습니다(알림이 늘지 않음). 처음 나눈 글이 혼자 남지 않게, 멤버가 반겨 줄 기회를 만드는 장치입니다(GRATO-51).</p><table tabindex="0"><thead><tr><th>항목</th><th>내용</th></tr></thead><tbody><tr><td>판정</td><td><code>onGratitudeCreated</code>의 4단계(Circle 알림)에서 <code>claimFirstShare</code>(<code>notifications/firstShare.ts</code>). 표시 문서 <code>circleFirstShares/{groupId}_{uid}</code>가 없을 때만 트랜잭션으로 만들고, 처음 만든 글이면 첫 나눔 → <a href="/grato-docs/architecture/data-model#circle-first-shares">데이터 모델</a></td></tr><tr><td>예전부터 쓴 사람</td><td>표시 문서가 없더라도 그 Circle에 이미 쓴 글이 있으면(작성자·Circle로 최대 3개 조회, 이 글보다 먼저인 글) 첫 나눔이 아님 → <code>legacy: true</code> 표시만 남기고 문구는 그대로</td></tr><tr><td>지웠다 다시 쓰기</td><td>표시 문서는 글을 지워도 남아서 두 번 &quot;처음&quot;이 되지 않음</td></tr><tr><td>빼는 글</td><td>자동 숨김된 글(알림도 없음, 표시도 만들지 않아 다음 글이 첫 나눔), 모두의 감사방 글(새 글 알림 없음), &quot;나만 보기&quot; 글</td></tr><tr><td>리더 자신의 첫 글</td><td>같은 문구로 멤버에게 감</td></tr><tr><td>알림 data</td><td><code>type: &quot;circle_post&quot;</code> 그대로 + <code>variant: &quot;first&quot;</code>. 클릭 경로(<code>/gratitude/{id}</code>)가 같아 <strong>앱 업데이트 없이</strong> 동작</td></tr><tr><td>글 표시</td><td>첫 나눔이면 같은 트랜잭션에서 글에 <code>firstShare: true</code>(Circle 피드의 &quot;처음 나눈 감사&quot;, 앱 iOS 1.0.1 (5)부터) → <a href="/grato-docs/features/circles#first-share">첫 나눔</a></td></tr><tr><td>판정 실패</td><td>오류가 나면 보통 새 글 알림으로 보냄(로그만)</td></tr><tr><td>쓰는 사람에게</td><td>아무것도 보이지 않음. &quot;반응 없음&quot;·읽음 표시 없음</td></tr></tbody></table><p>판단은 순수 함수 <code>notifications/firstSharePlan.ts</code>(<code>test/firstShare.test.ts</code>), 문구는 <code>utils/noticeCopy.ts</code>의 <code>firstShareNoticeTitle</code>입니다. 두 글을 거의 동시에 한 Circle에 처음 올리면 둘 다 보통 문구가 될 수 있습니다(표시 문서는 한 번만 만들어짐, 해는 없음).</p><p>알림을 눌러 생기는 <code>notification_clicked</code> 이벤트는 <code>props.variant</code>에 <code>&quot;first&quot;</code>를 담습니다(웹 포그라운드 알림과 앱). 웹의 백그라운드 알림 클릭은 서비스 워커가 처리해 지금은 이벤트를 남기지 않습니다(종류와 상관없이 같음).</p><h3 id="first-share-followup" tabindex="-1">24시간 뒤 리더에게 한 번 <a class="header-anchor" href="#first-share-followup" aria-label="Permalink to &quot;24시간 뒤 리더에게 한 번 {#first-share-followup}&quot;">​</a></h3><p>첫 나눔에 실제 사람의 반응이 닿을 두 번째 기회입니다. 모임을 연 리더에게만, 필요할 때 한 번 갑니다(GRATO-77). 쓰는 사람에게는 아무것도 가지 않습니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>첫 나눔 저장 → onGratitudeCreated: 첫 나눔 표시 + 멤버 알림 + Cloud Tasks 작업 예약</span></span>
<span class="line"><span>24시간 뒤(밤이면 다음 09:00 KST) → firstShareFollowup</span></span>
<span class="line"><span>  └ 조건을 모두 만족하면 리더에게 한 번, 아니면 이유만 기록</span></span></code></pre></div><table tabindex="0"><thead><tr><th>조건 (모두)</th><th>아니면 기록하는 이유 (<code>followupSkipped</code>)</th></tr></thead><tbody><tr><td>글이 있음</td><td><code>deleted</code></td></tr><tr><td>숨겨지지 않음</td><td><code>hidden</code></td></tr><tr><td>아직 그 Circle 글(<code>groupId</code> 그대로)</td><td><code>moved</code></td></tr><tr><td>작성자 말고는 공감·댓글이 하나도 없음</td><td><code>responded</code></td></tr><tr><td>Circle이 있고 모두의 감사방이 아님</td><td><code>circle_missing</code>, <code>open_circle</code></td></tr><tr><td>리더(<code>adminId</code>)가 있고 작성자가 아님</td><td><code>no_leader</code>, <code>leader_is_author</code> (이때는 예약도 하지 않음)</td></tr><tr><td>리더와 작성자가 아직 멤버</td><td><code>leader_not_member</code>, <code>author_left</code></td></tr><tr><td>리더 사용자 문서가 있고 <code>circlePostNotice</code>를 끄지 않음</td><td><code>leader_missing</code>, <code>notice_off</code></td></tr><tr><td>서로 차단하지 않음(양쪽 모두 확인)</td><td><code>blocked</code></td></tr><tr><td>리더가 오늘(KST) 이 알림을 아직 받지 않음</td><td><code>daily_cap</code> — 보내지 않고 쌓아 두지도 않음</td></tr></tbody></table><ul><li><strong>예약</strong>: 첫 나눔 표시를 만들 때 Cloud Tasks에 글마다 작업 하나(<code>onTaskDispatched</code>, 작업 ID <code>first_followup_{gratitudeId}</code> — 트리거가 다시 돌아도 하나). Cloud Scheduler 작업은 늘지 않습니다. 시각 계산은 <code>followupTime</code>(<code>notifications/firstShareFollowupPlan.ts</code>).</li><li><strong>기록</strong>: 표시 문서에 <code>followupAt</code>(판단한 시각), <code>followupSent</code>(true/false), <code>followupSkipped</code>(이유). 결과가 이미 있으면 다시 판단하지 않습니다. 하루 상한은 <code>notificationLogs/first_followup_leader_{uid}_{YYYYMMDD}</code>를 &quot;보냄&quot; 기록과 같은 트랜잭션에서 만들어 지킵니다. 그래서 같은 리더에게 하루 두 번 가지 않고, 보내기는 많아야 한 번입니다(보낸 직후 실패하면 다시 보내지 않음).</li><li><strong>알림 data</strong>: <code>type: &quot;circle_post&quot;</code>, <code>variant: &quot;first_followup&quot;</code>, <code>gratitudeId</code>, <code>groupId</code>. 클릭하면 그 글(<code>/gratitude/{id}</code>)이 열려 앱 업데이트가 필요 없습니다.</li><li><strong>끄기</strong>: 새 설정 없이 리더의 &quot;Circle 새 글 알림&quot;(<code>circlePostNotice</code>)을 따릅니다.</li><li><strong>문구</strong>: 소식으로 씁니다. &quot;반응이 없어요&quot;, &quot;아직&quot;, &quot;꼭&quot;, 숫자는 쓰지 않습니다(<code>utils/noticeCopy.ts</code>, 테스트가 확인).</li><li>판단은 순수 함수 <code>followupDecision</code>·<code>othersResponded</code>(<code>test/firstShareFollowup.test.ts</code>). 댓글은 <code>commentCount</code>에서 작성자 몫(<code>commentAuthors</code>)을 뺀 값으로 보고, <code>commentAuthors</code>가 없는 글에 댓글이 있으면 반응이 있는 것으로 봅니다(짐작으로 리더를 부르지 않음).</li></ul><h2 id="알림-설정" tabindex="-1">알림 설정 <a class="header-anchor" href="#알림-설정" aria-label="Permalink to &quot;알림 설정&quot;">​</a></h2><p><code>users/{uid}.notificationSettings</code> (마이페이지 &gt; 설정에서 변경. 가입 직후 <a href="/grato-docs/features/account#writing-plan">언제 감사를 떠올릴까요?</a>에서 고른 때가 <code>dailyReminderHour/Minute</code>이 되고, &quot;이 시간에 알려 주세요&quot;를 누르면 <code>dailyReminder: true</code>):</p><table tabindex="0"><thead><tr><th>키</th><th>기본값</th><th>비고</th></tr></thead><tbody><tr><td><code>dailyReminder</code></td><td>true</td><td>서버는 <code>== true</code>인 사용자만 조회. 필드가 없으면 보내지 않음</td></tr><tr><td><code>dailyReminderHour</code></td><td>21</td><td>0~23, KST 시</td></tr><tr><td><code>dailyReminderMinute</code></td><td>0</td><td>0·15·30·45, KST 분. 없으면 0(분 단위 도입 전 설정)</td></tr><tr><td><code>reactionNotice</code></td><td>true</td><td>필드가 없으면 켜진 것으로 취급</td></tr><tr><td><code>circlePostNotice</code></td><td>true</td><td>필드가 없으면 켜진 것으로 취급</td></tr><tr><td><code>dailyReminderChannel</code></td><td>없음</td><td>앱만 씀. <code>&#39;local&#39;</code>이면 그 사용자의 휴대폰 앱이 매일 알림을 로컬 알림으로 띄우는 중 → 서버가 보내지 않음. 알림을 끄거나 로그아웃하면 <code>null</code></td></tr><tr><td><code>dailyReminderLocalAt</code></td><td>없음</td><td>앱이 <code>&#39;local&#39;</code>을 쓸 때의 서버 시각. 하루에 한 번까지 갱신, 14일이 지나면 서버가 <code>&#39;local&#39;</code>을 무시</td></tr></tbody></table><p>설정은 <code>notificationSettings.&lt;키&gt;</code> 점 표기법으로 한 키씩 갱신해, 클라이언트가 모르는 새 키를 지우지 않습니다.</p><h2 id="message-shape" tabindex="-1">메시지 모양: 웹은 데이터 전용, 앱은 notification <a class="header-anchor" href="#message-shape" aria-label="Permalink to &quot;메시지 모양: 웹은 데이터 전용, 앱은 notification {#message-shape}&quot;">​</a></h2><p><code>utils/messaging.ts</code>의 <code>sendToUser</code>는 사용자의 토큰마다 <code>buildPushMessage</code>로 메시지를 만듭니다. 토큰 문서의 <code>platform</code>(<code>web</code> · <code>ios</code> · <code>android</code>, 없거나 모르는 값은 <code>web</code>)에 따라 모양이 다릅니다. 어느 쪽이든 <code>data</code>에 <code>title</code>, <code>body</code>, <code>type</code>, <code>gratitudeId</code> 등이 들어갑니다.</p><table tabindex="0"><thead><tr><th>플랫폼</th><th>메시지</th><th>이유</th></tr></thead><tbody><tr><td><code>web</code></td><td><strong>데이터 전용</strong> (최상위 <code>notification</code> 키 없음)</td><td><code>notification</code> 키가 있으면 브라우저가 알림을 자동으로 띄우고 서비스 워커도 띄워 <strong>두 번</strong> 보임. 표시는 서비스 워커(백그라운드)와 페이지(포그라운드)가 전적으로 맡음</td></tr><tr><td><code>ios</code>, <code>android</code></td><td><code>notification</code>(제목·본문) + 같은 <code>data</code>, APNs 기본 소리, Android 채널 <code>grato_push</code>·높은 우선순위</td><td>iOS는 데이터 전용 메시지를 시스템 알림으로 보여 주지 않고, Android도 백그라운드에서 데이터 전용 메시지를 표시하지 않음. 앱이 꺼져 있어도 OS가 표시</td></tr></tbody></table><h2 id="발송-흐름" tabindex="-1">발송 흐름 <a class="header-anchor" href="#발송-흐름" aria-label="Permalink to &quot;발송 흐름&quot;">​</a></h2>`,25)),(d(),r(s,null,{default:e(()=>[i(o,{id:"mermaid-580",class:"mermaid",graph:"sequenceDiagram%0A%20%20participant%20T%20as%20%ED%8A%B8%EB%A6%AC%EA%B1%B0%20%2F%20%EC%8A%A4%EC%BC%80%EC%A4%84%EB%9F%AC%0A%20%20participant%20L%20as%20notificationLogs%0A%20%20participant%20F%20as%20Firestore%0A%20%20participant%20M%20as%20FCM%0A%20%20participant%20D%20as%20%EA%B8%B0%EA%B8%B0%0A%20%20T-%3E%3EL%3A%20%EC%9D%B4%EB%B2%A4%ED%8A%B8%20ID%20%EC%B2%98%EB%A6%AC%20%EC%97%AC%EB%B6%80%20%ED%99%95%EC%9D%B8%0A%20%20alt%20%EC%9D%B4%EB%AF%B8%20%EC%B2%98%EB%A6%AC%EB%90%A8%0A%20%20%20%20T--%3E%3ET%3A%20%EA%B1%B4%EB%84%88%EB%9C%80%0A%20%20else%20%EC%B2%98%EC%9D%8C%0A%20%20%20%20T-%3E%3EF%3A%20%EB%B0%9B%EB%8A%94%20%EC%82%AC%EB%9E%8C%20%EC%84%A4%EC%A0%95%20%C2%B7%20pushTokens%20%EC%A1%B0%ED%9A%8C%0A%20%20%20%20T-%3E%3EM%3A%20%ED%86%A0%ED%81%B0%EB%A7%88%EB%8B%A4%20%ED%94%8C%EB%9E%AB%ED%8F%BC%EC%97%90%20%EB%A7%9E%EB%8A%94%20%EB%A9%94%EC%8B%9C%EC%A7%80%20(%EB%B3%91%EB%A0%AC)%0A%20%20%20%20M--%3E%3ED%3A%20%EC%84%9C%EB%B9%84%EC%8A%A4%20%EC%9B%8C%EC%BB%A4(%EC%9B%B9)%20%EB%98%90%EB%8A%94%20OS(%EC%95%B1)%EA%B0%80%20%ED%91%9C%EC%8B%9C%0A%20%20%20%20M--%3E%3ET%3A%20%EB%AC%B4%ED%9A%A8%20%ED%86%A0%ED%81%B0%20%EC%98%A4%EB%A5%98%EB%A9%B4%20%ED%86%A0%ED%81%B0%20%EB%AC%B8%EC%84%9C%20%EC%82%AD%EC%A0%9C%0A%20%20%20%20T-%3E%3EL%3A%20processed%20%EA%B8%B0%EB%A1%9D%20(30%EC%9D%BC%20TTL)%0A%20%20end%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[a(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=c('<ul><li>토큰이 없는 사용자는 오류가 아니라 건너뜁니다.</li><li><code>messaging/invalid-registration-token</code>, <code>messaging/registration-token-not-registered</code> 오류가 나면 그 토큰 문서를 지웁니다.</li><li>기록은 발송 <strong>뒤에</strong> 남기므로, 발송 직후 함수가 죽으면 재시도 때 한 번 더 갈 수 있습니다(최선 노력 방식의 중복 방지).</li></ul><h2 id="웹-클라이언트" tabindex="-1">웹 클라이언트 <a class="header-anchor" href="#웹-클라이언트" aria-label="Permalink to &quot;웹 클라이언트&quot;">​</a></h2><p>앱의 차이는 <a href="#app">아래</a>에 있습니다.</p><h3 id="토큰-등록" tabindex="-1">토큰 등록 <a class="header-anchor" href="#토큰-등록" aria-label="Permalink to &quot;토큰 등록&quot;">​</a></h3><p><code>pushTokens/{uid}/tokens/{token}</code>에 <code>{token, platform: &#39;web&#39;, userAgent, createdAt}</code>을 저장합니다(앱은 <code>{token, platform: &#39;ios&#39; | &#39;android&#39;, createdAt}</code> → <a href="#app">앱</a>). 토큰 문자열을 문서 ID로 써서 같은 기기를 다시 등록해도 문서가 하나입니다.</p><ul><li>로그인할 때마다 <code>registerPushToken(uid)</code>를 부르지만, 권한이 이미 <code>granted</code>일 때만 토큰을 저장합니다. <strong>권한 창을 자동으로 띄우지 않습니다.</strong></li><li>권한 요청은 사용자가 버튼을 눌렀을 때만 합니다(<code>enablePushNotifications</code>). 브라우저는 사용자 동작 없는 권한 요청을 막거나 사용자가 거부하기 쉬우므로, 거부되면 다시 물을 수 없기 때문입니다.</li></ul><h3 id="권한-ux" tabindex="-1">권한 UX <a class="header-anchor" href="#권한-ux" aria-label="Permalink to &quot;권한 UX&quot;">​</a></h3><table tabindex="0"><thead><tr><th>위치</th><th>동작</th></tr></thead><tbody><tr><td>홈 <code>PushPromptCard</code></td><td>권한이 <code>default</code>이고 FCM을 지원하는 브라우저에서만 표시. &quot;알림 받기&quot;를 누르면 권한 요청. 닫으면 <code>localStorage</code>의 <code>push-prompt-dismissed</code>에 기억</td></tr><tr><td>홈 <code>AppInstallCard</code></td><td>iPhone·iPad 웹에서 웹 푸시 API(<code>Notification</code>·<code>PushManager</code>·서비스 워커)가 없을 때만 표시. &quot;알림은 Grato 앱에서 받을 수 있어요&quot; + <strong>App Store에서 받기</strong>. 권한을 묻지 않음. 닫으면 <code>localStorage</code>의 <code>app-install-push-dismissed</code>(위 카드와 다른 키)에 기억 → <a href="#ios-web">iPhone·iPad 웹</a></td></tr><tr><td>가입 직후 <code>/welcome/plan</code></td><td>&quot;이 시간에 알려 주세요&quot;를 누를 때만 권한 요청(<code>askNotificationPermission</code>: 웹은 권한 답을 받는 즉시 돌아오고 토큰 등록은 뒤에서, 앱은 OS 권한). 다른 버튼은 묻지 않음 → <a href="/grato-docs/features/account#writing-plan">언제 감사를 떠올릴까요?</a></td></tr><tr><td>홈 <code>WritingPlanCard</code></td><td><code>writingPlan</code>이 없는 계정(초대 링크 가입, 기능 전 가입)에 한 번. 이 카드가 있는 동안 <code>PushPromptCard</code>는 숨김(알림은 계획 화면에서 물음). 닫으면 <code>grato:writingPlanCard:{uid}</code></td></tr><tr><td>MyPage 알림 설정</td><td>기기의 푸시 상태(지원 여부, 권한, 등록된 토큰 수)를 보여 주고 켜기 버튼 제공. 종류별 토글과 매일 알림 시각 선택. 이 브라우저가 알림을 지원하지 않으면 시각 아래 설명이 &quot;이 브라우저에서는 알림이 오지 않아요. 위 안내를 확인해 주세요&quot;</td></tr></tbody></table><h3 id="ios-web" tabindex="-1">iPhone·iPad 웹: App Store 앱 안내 <a class="header-anchor" href="#ios-web" aria-label="Permalink to &quot;iPhone·iPad 웹: App Store 앱 안내 {#ios-web}&quot;">​</a></h3><p>iPhone·iPad의 브라우저는 모두 같은 엔진이라 Safari 탭, Chrome, 카카오톡 안 브라우저 모두 웹 알림을 띄우지 못합니다(<code>Notification</code>이 없음). &quot;다른 브라우저&quot;는 답이 아니므로 App Store의 Grato 앱을 안내합니다. 같은 계정으로 로그인하면 기록과 알림 설정(시각 포함)이 그대로 이어집니다.</p><table tabindex="0"><thead><tr><th>환경</th><th>설정 상태 카드</th><th>홈</th></tr></thead><tbody><tr><td>iPhone·iPad 웹, 알림 미지원</td><td>&quot;알림은 Grato 앱에서 받을 수 있어요&quot; + 설명 + <strong>App Store에서 받기</strong>(새 창, <code>APP_STORE_URL</code>)</td><td><code>AppInstallCard</code></td></tr><tr><td>그 밖의 미지원 브라우저 (Android·PC)</td><td>&quot;이 브라우저에서 알림을 지원하지 않아요 / 다른 브라우저를 사용해보세요&quot; (그대로)</td><td>없음</td></tr><tr><td>알림을 지원하는 브라우저 (홈 화면에 추가한 웹 앱 포함)</td><td>권한 단계별 안내 (그대로)</td><td><code>PushPromptCard</code> (권한을 묻기 전)</td></tr><tr><td>Grato 앱</td><td>늘 지원 — 이 안내는 나오지 않음</td><td>그대로</td></tr></tbody></table><ul><li><strong>판정</strong>은 기능 감지와 기기 판별만 씁니다(<code>src/lib/pushHelp.js</code>, 순수 함수 + 테스트). iOS 기기는 <code>isIOSDevice({userAgent, platform, maxTouchPoints})</code>(<code>src/lib/platform.js</code>): iPhone·iPad·iPod, 그리고 데스크톱 사이트를 요청하는 iPadOS(<code>MacIntel</code> + 터치 지점 2개 이상). 설정 카드는 <code>getPushStatus</code>의 <code>supported</code>(FCM <code>isSupported()</code>까지)와 <code>iosWeb</code>으로, 홈 카드는 FCM을 불러오지 않고 API 유무(<code>webPushCapable</code>)로 정합니다.</li><li><strong>홈 화면에 추가한 웹 앱</strong>(iOS 16.4 이상)은 웹 푸시 API가 있을 수 있어, 있으면 다른 브라우저처럼 권한 단계 안내를 따릅니다. FCM이 그곳을 지원하지 않는다고 하면 설정 카드는 App Store 안내가 됩니다(홈 카드는 API 유무만 보므로 나오지 않음).</li><li><strong>웹에서만</strong> 보입니다. 앱(<code>isNative</code>)에서는 <code>getPushStatus</code>가 언제나 <code>iosWeb: false</code>이고 홈 카드도 그리지 않아, 앱 화면에 다른 플랫폼 이름이 들어가지 않습니다. Android 앱은 Play 정식 출시 전이라 Android 웹에는 앱을 안내하지 않습니다.</li><li><strong>분석</strong>: App Store 버튼을 누르면 <code>app_store_link_click</code>(<code>{from: &#39;push_status&#39; | &#39;home_card&#39;, standalone}</code>), <code>standalone</code>은 홈 화면에 추가한 웹 앱에서 눌렀는지.</li></ul><h3 id="표시" tabindex="-1">표시 <a class="header-anchor" href="#표시" aria-label="Permalink to &quot;표시&quot;">​</a></h3><ul><li><strong>백그라운드</strong>: 서비스 워커의 <code>onBackgroundMessage</code>가 <code>data.title</code>/<code>data.body</code>로 알림을 띄웁니다. 클릭하면 <code>data.type</code>에 맞는 경로(위 표의 &quot;클릭 시&quot;)로, 열린 창이 있으면 그 창을 이동·포커스하고, 없으면 새 창을 엽니다.</li><li><strong>포그라운드</strong>: <code>App.jsx</code>가 <code>onMessage</code>로 받아 브라우저 <code>Notification</code>을 띄우고, 클릭 시 같은 경로로 이동하며 <code>notification_clicked</code> 이벤트를 남깁니다.</li></ul><h2 id="question-selected" tabindex="-1">질문 선정 알림 (<code>question_selected</code>) <a class="header-anchor" href="#question-selected" aria-label="Permalink to &quot;질문 선정 알림 (`question_selected`) {#question-selected}&quot;">​</a></h2><p>제안한 질문을 운영자가 <strong>처음</strong> 선정하면 제안자에게 한 번 보냅니다. → <a href="/grato-docs/features/questions#after-approval">질문 제안과 선정</a></p><table tabindex="0"><thead><tr><th>항목</th><th>값</th></tr></thead><tbody><tr><td>보내는 곳</td><td><code>reviewQuestion</code> callable — 선정이 커밋된 뒤 (실패해도 선정은 취소되지 않음)</td></tr><tr><td>대상</td><td>사용자가 제안한 질문(<code>source: &quot;user&quot;</code>)의 제안자. 기본 질문은 보내지 않음</td></tr><tr><td>조건</td><td>선정 전에 <code>approvedAt</code>이 없던 질문(처음 선정)만. 숨겼다가 다시 선정해도 다시 보내지 않음</td></tr><tr><td>중복 방지</td><td><code>notificationLogs/question_selected_{questionId}</code></td></tr><tr><td>끄는 설정</td><td>없음 (자기 제안에 대한 결과 안내)</td></tr><tr><td>메시지</td><td>제목 &quot;제안한 질문이 선정됐어요 🎉&quot;, 본문 질문 문구, <code>data: { type: &quot;question_selected&quot;, questionId }</code></td></tr><tr><td>클릭 시</td><td><code>/mypage#questions</code></td></tr></tbody></table><ul><li><strong>백그라운드</strong>: 서비스 워커가 <code>/mypage#questions</code>로 이동합니다.</li><li><strong>포그라운드</strong>: <code>App.jsx</code>가 이미 MyPage에 있으면 &quot;내가 제안한 질문&quot; 카드로 스크롤만 하고, 아니면 <code>/mypage#questions</code>로 이동합니다.</li><li>MyPage의 <code>MyQuestionsSection</code>은 목록을 그린 뒤 주소의 해시가 <code>#questions</code>이면 그 카드로 스크롤합니다.</li><li>반려는 알림을 보내지 않습니다. 제안자는 MyPage에서 상태와 사유를 봅니다.</li></ul><h2 id="daily-reminder" tabindex="-1">매일 알림 (<code>sendDailyReminder</code>) <a class="header-anchor" href="#daily-reminder" aria-label="Permalink to &quot;매일 알림 (`sendDailyReminder`) {#daily-reminder}&quot;">​</a></h2><p>웹(과 앱이 로컬 알림을 맡지 않은 사용자)의 서버 발송입니다. 앱의 휴대폰 자체 알림은 <a href="#local-reminder">아래</a>에 있습니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>값</th></tr></thead><tbody><tr><td>스케줄</td><td>15분마다 <code>*/15 * * * *</code>, 시간대 <code>Asia/Seoul</code> (예전 <code>every 1 hours</code>는 작업 생성 시각 기준이라 매시 40분에 돌았음)</td></tr><tr><td>대상 조회</td><td><code>dailyReminder == true</code>, <code>dailyReminderHour == 현재 KST 시</code>, 그리고 정각이 아니면 <code>dailyReminderMinute == 현재 15분 구간</code> (복합 인덱스). 정각 실행은 분 필드가 없는 예전 설정도 함께 처리</td></tr><tr><td>건너뛰기</td><td><code>userStats</code>로 확인해 <strong>오늘(KST) 이미 쓴 사용자</strong>. 그리고 앱이 로컬 알림을 맡은 사용자(<code>dailyReminderChannel == &#39;local&#39;</code>, <code>dailyReminderLocalAt</code>이 14일 안, <code>LOCAL_REMINDER_TTL_MS</code>) — 조회 뒤 메모리에서 거름(<code>reminderRecipients</code>), 로그에 <code>app-local</code> 수</td></tr><tr><td>처리 단위</td><td>100명씩 <code>userStats</code>를 한 번에 읽고 병렬 발송</td></tr><tr><td>중복 방지</td><td><code>daily_reminder_{uid}_{YYYYMMDD}_{HHMM}</code></td></tr><tr><td>제한</td><td>타임아웃 300초, 최대 인스턴스 3</td></tr></tbody></table><p>조회 조건에 시각을 넣어, 읽는 문서 수가 전체 사용자 수가 아니라 그 시각의 대상자 수에 비례합니다.</p><h3 id="daily-reminder-copy" tabindex="-1">매일 알림 문구: 고른 때를 말함 <a class="header-anchor" href="#daily-reminder-copy" aria-label="Permalink to &quot;매일 알림 문구: 고른 때를 말함 {#daily-reminder-copy}&quot;">​</a></h3><p><a href="/grato-docs/features/account#writing-plan">언제 감사를 떠올릴까요?</a>에서 고른 때가 알림에서 다시 보이게 합니다. &quot;잠들기 전이 되면 → 한 줄&quot;의 단서를 알림이 그대로 말합니다.</p><table tabindex="0"><thead><tr><th>쓰기로 한 때 (<code>writingPlan.cue</code>)</th><th>제목</th></tr></thead><tbody><tr><td><code>morning</code> 아침 차 한 잔 할 때</td><td>아침 한 모금과 함께, 오늘의 감사 한 줄 ☕</td></tr><tr><td><code>commute</code> 출근·등교길</td><td>가는 길에 떠오른 고마운 일, 한 줄 남겨 볼까요? 🚌</td></tr><tr><td><code>lunch</code> 점심 먹고 나서</td><td>점심 뒤 잠깐, 오늘의 감사 한 줄 🍚</td></tr><tr><td><code>evening</code> 퇴근·하교길</td><td>돌아오는 길, 오늘 고마웠던 일 하나 🌆</td></tr><tr><td><code>bedtime</code> 잠들기 전</td><td>잠들기 전, 오늘의 감사 한 줄 🌙</td></tr><tr><td><code>custom</code> 내가 정한 때 · 계획 없음</td><td>오늘의 감사를 기록해보세요 🙏 (예전 그대로)</td></tr></tbody></table><ul><li>본문은 모두 &quot;하루를 돌아보며 감사한 순간을 적어볼까요?&quot;</li><li>알림 시각이 계획의 시각과 같을 때만 때 문구를 씁니다. 설정에서 알림 시각만 바꿨으면(예: 잠들기 전으로 정했는데 오전 7시) 예전 문구로 돌아갑니다.</li><li><strong>문구는 한 파일</strong>: <code>src/content/reminderCopy.json</code>과 <code>functions/src/notifications/reminderCopy.json</code>은 같은 파일이고(클라이언트 테스트가 확인), 고르는 규칙은 순수 함수 <code>reminderMessage</code>(앱 <code>src/lib/reminderCopy.js</code>, 서버 <code>functions/src/notifications/reminderCopy.ts</code>, 같은 테스트 사례)입니다. 서버 <code>sendDailyReminder</code>(웹 푸시)와 앱 <code>localReminders</code>(휴대폰 알림, 날마다 따로 계산)가 같이 씁니다.</li><li><strong>시즌 문구와 겹칠 때</strong>: JSON의 <code>seasons</code>(<code>{seasonKey, from, to, title, core?, body?}</code>, KST 날짜 포함 범위, <a href="/grato-docs/features/guided-writing#season-questions">시즌 질문</a>과 같은 날짜 — 클라이언트 테스트가 확인)에 든 기간에는 시즌 문구가 이기고, 고른 때가 있으면 앞의 단서와 이모지만 붙입니다: <code>&quot;{lead}, {core} {emoji}&quot;</code> → &quot;잠들기 전, 한 해 돌아보기 질문 하나 🌙&quot;. 때가 없으면 시즌 <code>title</code>. 지금 <code>seasons</code>는 비어 있습니다(시즌 문구는 별도 작업에서 채움).</li><li>알림 횟수·조건(하루 한 번, 그날 쓴 사람 건너뜀, 앱 14일 예약)은 바뀌지 않습니다. 손실을 앞세우는 말(&quot;끊겨요&quot;, &quot;사라져요&quot;)은 쓰지 않습니다(테스트가 확인).</li><li>때 문구로 보낸 알림은 <code>data.cue</code>를 싣고, 누르면 <code>notification_clicked {type: &#39;daily_reminder&#39;, cue}</code>가 남습니다(웹 포그라운드·앱 푸시·앱 휴대폰 알림). 웹에서 브라우저가 띄운 알림(백그라운드)을 누른 것은 지금처럼 기록되지 않습니다.</li></ul><p><strong>시즌 문구</strong> (초안, 확정은 오너). 고른 때가 있으면 제목은 <code>{lead}, {core} {emoji}</code>(예: &quot;잠들기 전, 감사의 계절 질문 하나 🌙&quot;), 없으면 아래 제목입니다.</p><table tabindex="0"><thead><tr><th>날짜 (KST)</th><th>제목</th><th>본문</th></tr></thead><tbody><tr><td>기본</td><td>오늘의 감사를 기록해보세요 🙏</td><td>하루를 돌아보며 감사한 순간을 적어볼까요?</td></tr><tr><td>11/15–11/30</td><td>오늘의 감사의 계절 질문이 기다려요 🍂</td><td>올해 거둔 고마움을 한 줄 적어볼까요?</td></tr><tr><td>12/1–12/31</td><td>오늘의 한 해 돌아보기 질문이 기다려요 ❄️</td><td>올해를 떠올리며 고마웠던 순간을 한 줄 적어볼까요?</td></tr><tr><td>1/1–1/10</td><td>오늘의 신년 감사 질문이 기다려요 🌅</td><td>새해의 고마운 마음을 한 줄 남겨 볼까요?</td></tr></tbody></table><p>시즌 문구는 초안입니다(확정은 오너). 신년 문구는 그날의 질문이 신년 질문인 1/10까지만 씁니다. 그날 시즌 질문을 운영자가 숨겨도 알림 문구는 시즌판입니다.</p><h2 id="app" tabindex="-1">앱 (iOS·Android) <a class="header-anchor" href="#app" aria-label="Permalink to &quot;앱 (iOS·Android) {#app}&quot;">​</a></h2><p>앱은 웹과 같은 알림 종류·설정·클릭 경로를 쓰고, 받는 방법만 네이티브입니다. 설정 절차(APNs 키, 채널)는 <a href="/grato-docs/mobile/#push">iOS·Android 앱</a>에 있습니다.</p><h3 id="푸시" tabindex="-1">푸시 <a class="header-anchor" href="#푸시" aria-label="Permalink to &quot;푸시&quot;">​</a></h3><table tabindex="0"><thead><tr><th>항목</th><th>앱에서</th></tr></thead><tbody><tr><td>플러그인</td><td><code>@capacitor-firebase/messaging</code> (<code>src/lib/native/push.js</code>, 앱에서만 불러옴)</td></tr><tr><td>토큰</td><td><code>pushTokens/{uid}/tokens/{token}</code> = <code>{token, platform: &#39;ios&#39; | &#39;android&#39;, createdAt}</code>. 권한이 이미 있을 때만 로그인 뒤 저장하고, 같은 토큰은 하루에 한 번까지 다시 씀. 토큰이 바뀌면(<code>tokenReceived</code>) 이 기기의 예전 문서를 지움</td></tr><tr><td>권한</td><td>OS 권한 하나가 푸시와 매일 알림을 함께 덮음. 홈 <code>PushPromptCard</code>(&quot;매일 감사 알림과 Circle 소식을 알려드려요&quot;), MyPage &quot;알림 켜기&quot;, MyPage에서 매일 알림을 켤 때만 요청. 자동으로 묻지 않음</td></tr><tr><td>거부했을 때</td><td>MyPage: &quot;알림이 꺼져 있어요 / 휴대폰 설정 › Grato › 알림에서 허용해 주세요&quot;. 설정에서 허용하고 돌아오면 토큰을 저장</td></tr><tr><td>백그라운드</td><td>OS가 <code>notification</code> 페이로드를 표시 → <a href="#message-shape">메시지 모양</a></td></tr><tr><td>포그라운드</td><td>iOS: OS가 배너·소리·배지로 표시. Android: 앱이 받아 같은 채널(<code>grato_push</code>)의 로컬 알림으로 표시</td></tr><tr><td>클릭</td><td>웹 서비스 워커와 같은 경로(<code>notifyHelpers.notificationPath</code>). 이미 MyPage면 질문 카드로 스크롤만. <code>notification_clicked</code> 이벤트에 <code>platform</code></td></tr><tr><td>로그아웃</td><td>토큰 문서와 FCM 토큰을 지움(남은 문서가 있어도 아무에게도 가지 않음)</td></tr></tbody></table><h3 id="local-reminder" tabindex="-1">매일 알림: 휴대폰 자체 알림 <a class="header-anchor" href="#local-reminder" aria-label="Permalink to &quot;매일 알림: 휴대폰 자체 알림 {#local-reminder}&quot;">​</a></h3><p>앱에서는 서버 푸시 대신 <code>@capacitor/local-notifications</code>로 휴대폰이 직접 띄웁니다(<code>src/lib/native/localReminders.js</code>). → <a href="/grato-docs/decisions#adr-16">결정 기록 #16</a></p><ul><li>시각은 웹과 같은 설정(KST, 15분 단위). 앞으로 14일 치를 하루씩 예약하고, 오늘 이미 썼거나 시각이 지났으면 오늘은 뺍니다.</li><li>문구는 서버와 같은 <a href="#daily-reminder-copy">매일 알림 문구</a>를 날마다 계산합니다(시즌이 시작되는 날부터 시즌 문구). 쓰기로 한 때나 문구가 바뀌면 다시 예약합니다.</li><li>앱 시작·복귀, 설정 변경, 글 저장, 권한 허용 때 다시 맞춥니다. 설정 화면 안내: &quot;매일 이 시간에 이 휴대폰으로 알려드려요. 기록한 날은 쉬어요 (15분 단위)&quot;.</li><li>Android 채널 <code>daily_reminder</code>(&quot;매일 감사 알림&quot;). 정확한 알람 권한은 쓰지 않아 절전 중에는 몇 분 늦을 수 있습니다.</li><li>예약하는 동안 <code>notificationSettings.dailyReminderChannel = &#39;local&#39;</code>과 <code>dailyReminderLocalAt</code>(서버 시각)을 한 번에 씁니다. 서버는 이 표시가 14일 안이면 그 사용자에게 매일 알림을 보내지 않습니다(웹 브라우저 포함, 하루 한 번만). 알림을 끄거나 권한이 없거나 로그아웃하면 <code>null</code>로 되돌려 서버 알림이 다시 갑니다. 앱을 지워 되돌리지 못해도 14일 뒤 만료됩니다.</li></ul>',36)),(d(),r(s,null,{default:e(()=>[i(o,{id:"mermaid-1239",class:"mermaid",graph:"sequenceDiagram%0A%20%20participant%20A%20as%20%EC%95%B1%20(%ED%9C%B4%EB%8C%80%ED%8F%B0)%0A%20%20participant%20F%20as%20users%2F%7Buid%7D%0A%20%20participant%20S%20as%20sendDailyReminder%0A%20%20A-%3E%3EA%3A%2014%EC%9D%BC%20%EC%B9%98%20%EB%A1%9C%EC%BB%AC%20%EC%95%8C%EB%A6%BC%20%EC%98%88%EC%95%BD%20(%EC%98%A4%EB%8A%98%20%EC%8D%BC%EC%9C%BC%EB%A9%B4%20%EB%82%B4%EC%9D%BC%EB%B6%80%ED%84%B0)%0A%20%20A-%3E%3EF%3A%20dailyReminderChannel%20%3D%20'local'%2C%20dailyReminderLocalAt%20%3D%20%EC%84%9C%EB%B2%84%20%EC%8B%9C%EA%B0%81%20(%ED%95%98%EB%A3%A8%20%ED%95%9C%20%EB%B2%88%EA%B9%8C%EC%A7%80)%0A%20%20S-%3E%3EF%3A%20%EA%B7%B8%20%EC%8B%9C%EA%B0%81%20%EB%8C%80%EC%83%81%20%EC%A1%B0%ED%9A%8C%0A%20%20S--%3E%3ES%3A%20'local'%EC%9D%B4%EA%B3%A0%2014%EC%9D%BC%20%EC%95%88%EC%9D%B4%EB%A9%B4%20%EA%B1%B4%EB%84%88%EB%9C%80%0A%20%20Note%20over%20A%3A%20%EC%A0%95%ED%95%9C%20%EC%8B%9C%EA%B0%81%EC%97%90%20%ED%9C%B4%EB%8C%80%ED%8F%B0%EC%9D%B4%20%EC%A7%81%EC%A0%91%20%EC%95%8C%EB%A6%BC%20%E2%86%92%20%EB%88%84%EB%A5%B4%EB%A9%B4%20%2Fwrite%0A"})]),fallback:e(()=>[...t[1]||(t[1]=[a(" Loading... ",-1)])]),_:1}))])}const B=l(h,[["render",p]]);export{m as __pageData,B as default};
